package com.picviewer.app;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.app.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import javax.crypto.*;import javax.crypto.spec.*;
@RunWith(RobolectricTestRunner.class) @org.robolectric.annotation.Config(sdk=34,qualifiers="w600dp-h960dp-port-mdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE) @LooperMode(LooperMode.Mode.PAUSED)
public class StabilityTest {
 public static class TestActivity extends MainActivity {@Override long frameBudget(){return 32*NextFrame.MIB;}}
 MainActivity a;SavedConnections saved;
 @Before public void setup()throws Exception{a=Robolectric.buildActivity(TestActivity.class).setup().get();android.app.ActivityManager.MemoryInfo memory=new android.app.ActivityManager.MemoryInfo();memory.availMem=1024L*1024*1024;memory.threshold=64L*1024*1024;org.robolectric.Shadows.shadowOf((android.app.ActivityManager)a.getSystemService(android.content.Context.ACTIVITY_SERVICE)).setMemoryInfo(memory);KeyGenerator g=KeyGenerator.getInstance("AES");g.init(128);java.security.Key key=g.generateKey();saved=new SavedConnections(a,(encrypt,text)->{Cipher c=Cipher.getInstance("AES/GCM/NoPadding");if(encrypt){c.init(Cipher.ENCRYPT_MODE,key);return Base64.getEncoder().encodeToString(c.getIV())+":"+Base64.getEncoder().encodeToString(c.doFinal(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}String[] x=text.split(":",2);c.init(Cipher.DECRYPT_MODE,key,new GCMParameterSpec(128,Base64.getDecoder().decode(x[0])));return new String(c.doFinal(Base64.getDecoder().decode(x[1])),java.nio.charset.StandardCharsets.UTF_8);});}
 @After public void end(){a.onDestroy();}
 Config fixture(){Config c=new Config();c.host="synthetic-pc";c.share="synthetic-photos";c.root="여행";c.user="synthetic-reader";c.password="synthetic-password";return c;}
 @Test public void encryptedProfileRoundTrip()throws Exception{Config c=fixture();saved.save("거실 액자",c);SavedConnections.Profile p=saved.all().get(0);assertEquals(c.source(),p.config.source());assertEquals(c.password,p.config.password);String persisted=saved.prefs.getAll().toString();for(String secret:new String[]{c.host,c.user,c.password,c.share,"거실 액자"})assertFalse(persisted.contains(secret));}
 @Test public void profileUpdateKeepsOneIdentity()throws Exception{Config c=fixture();saved.save("이전",c);c.password="synthetic-changed";saved.save("변경",c);assertEquals(1,saved.all().size());assertEquals(c.password,saved.all().get(0).config.password);}
 @Test public void deletingProfileDoesNotChangeActiveConnection()throws Exception{saved.save("삭제",fixture());a.config=fixture();saved.remove(saved.all().get(0).id);assertTrue(saved.all().isEmpty());assertEquals("synthetic-pc",a.config.host);}
 @Test public void profileLimitDoesNotEvictOldConnections()throws Exception{for(int i=0;i<20;i++){Config c=fixture();c.host+="-"+i;saved.save("연결 "+i,c);}try{saved.save("넘침",fixture());fail();}catch(IOException expected){}assertEquals(20,saved.all().size());}
 @Test public void corruptProfilesNeverBecomeEmptySuccess()throws Exception{saved.prefs.edit().putString("encrypted","corrupt").commit();try{saved.all();fail();}catch(Exception expected){}try{saved.save("새 값",fixture());fail();}catch(Exception expected){}assertEquals("corrupt",saved.prefs.getString("encrypted",""));}
 @Test public void loadingProfileDoesNotConnectOrLoseShare(){a.connectionDialog();ConnectionDialog c=a.connectionUi;c.fill(fixture(),"거실");assertEquals("synthetic-photos",c.selected);assertEquals("여행",c.input(true).root);assertEquals("synthetic-password",c.pass.getText().toString());assertNull(c.sharesJob);assertNull(c.discoveryJob);assertEquals("",a.config.host);}
 @Test public void transportRetryExactlyOnce()throws Exception{try(SmbSource s=new SmbSource(fixture())){int[] n={0};assertEquals("ok",s.retry(()->{if(n[0]++==0)throw new java.net.SocketException("Connection reset");return "ok";}));assertEquals(2,n[0]);}}
 @Test public void repeatedTransportFailureStopsAfterTwo()throws Exception{try(SmbSource s=new SmbSource(fixture())){int[] n={0};try{s.retry(()->{n[0]++;throw new java.net.SocketTimeoutException();});fail();}catch(java.net.SocketTimeoutException expected){}assertEquals(2,n[0]);}}
 @Test public void passwordAndFileErrorsNeverRetry()throws Exception{for(String error:new String[]{"STATUS_LOGON_FAILURE","STATUS_ACCESS_DENIED","FILE_CHANGED_SINCE_SCAN","FILE_LIMIT","No space left on device","STATUS_SHARING_VIOLATION"})try(SmbSource s=new SmbSource(fixture())){int[] n={0};try{s.retry(()->{n[0]++;throw new IOException(error);});fail();}catch(IOException expected){}assertEquals(error,1,n[0]);}}
 @Test public void unknownFileErrorsAreNotPcOffline(){assertEquals("FILE",SmbSource.kind(new IOException("unsupported query")));assertEquals("STORAGE",SmbSource.kind(new Images.TransportFailure(new IOException("ENOSPC"))));assertEquals("BUSY",SmbSource.kind(new IOException("STATUS_SHARING_VIOLATION")));assertEquals("AUTH",SmbSource.kind(new IOException(new IOException("STATUS_LOGON_FAILURE"))));}
 @Test public void allFoldersAvailableInPortraitDialog()throws Exception{a.startDemo();for(int i=0;i<80;i++)a.folders.add(String.format("폴더%03d/하위",i));a.gallery();a.folderDialog();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertEquals(a.folders.size(),d.getListView().getAdapter().getCount());capture(d.getWindow().getDecorView(),"all-folders-portrait",600,880);}
 @Test public void portraitGalleryRendersFolderCount()throws Exception{a.startDemo();a.gallery();assertTrue(((Button)a.sidebar.getChildAt(0)).getText().toString().contains("전체 목록"));capture(a.getWindow().getDecorView(),"portrait-folders",600,960);}
 @Test public void sourceLoadingRenders()throws Exception{a.connectionDialog();Config cfg=fixture();cfg.password="";a.connectionUi.fill(cfg,"거실 액자");capture(a.connectionUi.dialog.getWindow().getDecorView(),"saved-connection-form",600,880);}
 @Test public void playbackIntervalSavesCustomSecondsAndKeepsPaused()throws Exception{a.startDemo();a.startPlayback(null);a.paused=true;a.intervalDialog();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();LinearLayout form=(LinearLayout)((android.widget.FrameLayout)d.findViewById(android.R.id.custom)).getChildAt(0);EditText value=findEdit(form);value.setText("7");d.getButton(-1).performClick();assertEquals(7,a.seconds);assertEquals(7,a.prefs.getInt("seconds",0));assertTrue(a.paused);assertTrue(a.intervalButton.getText().toString().contains("7초"));}
 @Test public void invalidIntervalDoesNotDismissOrChange()throws Exception{a.startDemo();a.startPlayback(null);a.intervalDialog();Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();EditText value=findEdit(d.getWindow().getDecorView());value.setText("0");d.getButton(-1).performClick();assertTrue(d.isShowing());assertEquals(15,a.seconds);value.setText("3601");d.getButton(-1).performClick();assertTrue(d.isShowing());value.setText("15");value.setError(null);capture(d.getWindow().getDecorView(),"slideshow-interval",600,600);}
 EditText findEdit(View v){if(v instanceof EditText)return (EditText)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){EditText e=findEdit(((ViewGroup)v).getChildAt(i));if(e!=null)return e;}return null;}

 @Test public void nextFrameIsDecodedDuringCurrentDisplayAndConsumedWithoutDecode()throws Exception{a.startDemo();a.startPlayback(null);settle();String current=a.playlist.current(),next=a.nextPath();String key=a.lookup(next).key(a.config.source());assertTrue(a.nextFrame.has(key));Images.Decoded expected=a.nextFrame.take(key);a.nextFrame.put(key,expected);assertEquals(current,a.playlist.current());a.advance(false);settle();assertEquals(next,a.playlist.current());assertSame(expected.bitmap,a.shown);assertEquals(2,a.player.getChildCount());capture(a.getWindow().getDecorView(),"playback-prefetch",600,960);}
 @Test public void nextFrameOwnershipAndCancellation()throws Exception{NextFrame cache=new NextFrame();android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(20,20,android.graphics.Bitmap.Config.ARGB_8888);cache.put("a",new Images.Decoded(bitmap,""));assertNull(cache.take("b"));Images.Decoded taken=cache.take("a");cache.clear();assertFalse(taken.bitmap.isRecycled());cache.put("c",taken);cache.clear();assertTrue(bitmap.isRecycled());}
 @Test public void prefetchAuthFailureIsReturnedWithoutRelogin()throws Exception{NextFrame cache=new NextFrame();IOException expected=new IOException("STATUS_LOGON_FAILURE");cache.fail("a",expected);try{cache.take("a");fail();}catch(IOException e){assertSame(expected,e);}assertFalse(cache.has("a"));}
 @Test public void galleryAndPauseDiscardPrefetchedBitmap()throws Exception{a.startDemo();a.startPlayback(null);settle();String next=a.nextPath(),key=a.lookup(next).key(a.config.source());assertTrue(a.nextFrame.has(key));a.onPause();assertFalse(a.nextFrame.has(key));a.gallery();assertFalse(a.playing);}
 @Test public void randomPeekMatchesActualNextWithoutAdvancingCurrent(){a.startDemo();a.prefs.edit().putBoolean("random",true).commit();a.startPlayback(null);for(int i=0;i<10;i++){String expected=a.nextPath();String before=a.playlist.current();assertEquals(before,a.playlist.current());a.playlist.next(a.selected());assertEquals(expected,a.playlist.current());}}

 @Test public void prefetchReadFailureDoesNotInterruptCurrentPhoto()throws Exception{a.startDemo();a.startPlayback(null);settle();android.graphics.Bitmap current=a.shown;a.cancelPrefetch();com.picviewer.core.Photo bad=new com.picviewer.core.Photo("missing-fixture.jpg",1,1);a.all.add(bad);a.playlist.order.add(a.playlist.index+1,bad.path);a.prefetchNext();settle();assertSame(current,a.shown);assertEquals("",a.failure);assertTrue(a.playing);assertFalse(a.loadingCurrent);assertFalse(a.nextFrame.has(bad.key(a.config.source())));}
 @Test public void customIntervalSurvivesOtherSettings(){a.seconds=7;a.settings();AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();d.getButton(-1).performClick();assertEquals(7,a.seconds);}

 @Test public void adaptiveBudgetReservesMemoryAndHonorsPressure(){long m=1024L*1024;assertEquals(0,NextFrame.budget(128*m,100*m,0,512*m,64*m,false));assertEquals(0,NextFrame.budget(256*m,20*m,10*m,512*m,64*m,true));assertEquals(32*m,NextFrame.budget(256*m,20*m,10*m,1024*m,64*m,false));assertTrue(NextFrame.budget(256*m,130*m,10*m,512*m,64*m,false)<32*m);}
 @Test public void cacheStoresMultipleFramesThenShrinksAndRecycles()throws Exception{NextFrame cache=new NextFrame();cache.configure(100000,6);android.graphics.Bitmap b1=android.graphics.Bitmap.createBitmap(20,20,android.graphics.Bitmap.Config.ARGB_8888),b2=b1.copy(b1.getConfig(),false);cache.put("a",new Images.Decoded(b1,""));cache.put("b",new Images.Decoded(b2,""));assertTrue(cache.has("a"));assertTrue(cache.has("b"));cache.configure(0,0);assertTrue(b1.isRecycled());assertTrue(b2.isRecycled());assertEquals(0,cache.bytes);}
 @Test public void backwardSwipeUsesPriorDecodedFrame()throws Exception{a.startDemo();a.startPlayback(null);settle();android.graphics.Bitmap first=a.shown;String path=a.playlist.current();a.advance(false);settle();assertTrue(a.nextFrame.has(a.lookup(path).key(a.config.source())));a.advance(true);settle();assertSame(first,a.shown);}
 void settle()throws Exception{for(int i=0;i<10;i++){a.decode.submit(()->{}).get(20,java.util.concurrent.TimeUnit.SECONDS);Shadows.shadowOf(android.os.Looper.getMainLooper()).idle();}}
 void capture(View v,String name,int w,int h)throws Exception{v.measure(View.MeasureSpec.makeMeasureSpec(w,1073741824),View.MeasureSpec.makeMeasureSpec(h,1073741824));v.layout(0,0,w,h);v.jumpDrawablesToCurrentState();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));File out=new File(System.getProperty("picviewer.screenshots"));out.mkdirs();try(OutputStream o=new FileOutputStream(new File(out,name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
}
